// src/providers.ts
var CUSTOM_PROVIDER_ID = "companionheart";
function buildProviderRuntime(env = process.env) {
  const providerKind = env.LLM_PROVIDER ?? "custom";
  const modelId = env.LLM_MODEL;
  const apiKey = env.LLM_API_KEY ?? "";
  if (!modelId) throw new Error("\u7F3A\u5C11 LLM_MODEL \u73AF\u5883\u53D8\u91CF");
  const models = createModels();
  if (providerKind === "anthropic") {
    if (!apiKey) throw new Error("anthropic \u6A21\u5F0F\u7F3A\u5C11 LLM_API_KEY");
    models.setProvider(anthropicProvider());
    const model2 = models.getModel("anthropic", modelId);
    if (!model2) throw new Error(`\u6A21\u578B\u4E0D\u5728 Anthropic \u5185\u7F6E\u76EE\u5F55: ${modelId}`);
    return { models, model: model2, providerId: "anthropic", apiKey };
  }
  if (providerKind === "deepseek") {
    if (!apiKey) throw new Error("deepseek \u6A21\u5F0F\u7F3A\u5C11 LLM_API_KEY");
    models.setProvider(deepseekProvider());
    const model2 = models.getModel("deepseek", modelId);
    if (!model2) throw new Error(`\u6A21\u578B\u4E0D\u5728 DeepSeek \u5185\u7F6E\u76EE\u5F55: ${modelId}`);
    return { models, model: model2, providerId: "deepseek", apiKey };
  }
  const baseUrl = env.LLM_BASE_URL;
  if (!baseUrl) throw new Error("custom \u6A21\u5F0F\u7F3A\u5C11 LLM_BASE_URL");
  const model = {
    id: modelId,
    name: modelId,
    api: "openai-completions",
    provider: CUSTOM_PROVIDER_ID,
    baseUrl,
    reasoning: false,
    input: ["text"],
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    contextWindow: 65536,
    maxTokens: 8192,
    // 国产/自建兼容端点普遍不支持 developer role
    compat: { supportsDeveloperRole: false }
  };
  models.setProvider(
    createProvider({
      id: CUSTOM_PROVIDER_ID,
      name: "CompanionHeart LLM",
      baseUrl,
      auth: {
        apiKey: {
          name: "CompanionHeart LLM key",
          // Ollama 等无鉴权端点用占位 key，端点会忽略
          resolve: async () => ({ auth: { apiKey: apiKey || "none" }, source: "sidecar-env" })
        }
      },
      models: [model],
      api: openAICompletionsApi()
    })
  );
  return { models, model, providerId: CUSTOM_PROVIDER_ID, apiKey: apiKey || "none" };
}

